let pending: Promise<unknown> = Promise.resolve();

export function renderIssueDiagram(source: string, id: string, dark: boolean): Promise<string> {
	const render = pending.then(async () => {
		const { default: mermaid } = await import("mermaid");
		mermaid.initialize({
			startOnLoad: false,
			securityLevel: "strict",
			theme: dark ? "dark" : "neutral",
			htmlLabels: false,
			suppressErrorRendering: true,
		});
		const result = await mermaid.render(id, source);
		return result.svg;
	});
	pending = render.catch(() => {});
	return render;
}

import type { IssueInlineMedia } from "./rich-text.js";
import type { JSONContent } from "@tiptap/core";

export const statuses = ["backlog", "todo", "progress", "done", "canceled"] as const;
export const priorities = ["none", "urgent", "high", "medium", "low"] as const;

export type IssueStatus = (typeof statuses)[number];
export type IssuePriority = (typeof priorities)[number];

export type IssueComposerOption = {
	id: string;
	label: string;
	teamIds?: readonly string[];
};

export type IssueDraft = {
	title: string;
	description: string;
	descriptionContent?: JSONContent;
	status: IssueStatus;
	priority: IssuePriority;
	attachments: File[];
	inlineMedia?: IssueInlineMedia[];
	team?: string;
	assignee?: string;
	project?: string;
	labels?: string[];
};

export const issueLabels = {
	status: ["状态", "Status"],
	priority: ["优先级", "Priority"],
	backlog: ["待规划", "Backlog"],
	todo: ["待处理", "Todo"],
	progress: ["进行中", "In progress"],
	done: ["已完成", "Done"],
	canceled: ["已取消", "Canceled"],
	none: ["无优先级", "No priority"],
	urgent: ["紧急", "Urgent"],
	high: ["高", "High"],
	medium: ["中", "Medium"],
	low: ["低", "Low"],
} as const;

import { Node, mergeAttributes } from "@tiptap/core";
import { mount, unmount } from "svelte";
import IssueMediaBlock from "./issue-media-block.svelte";
import IssueSourceBlock from "./issue-source-block.svelte";
import { readImageCrop } from "./media-crop.js";
import { type IssueInlineMedia, type IssueSourceKind } from "./rich-text.js";

type RichNodeOptions = {
	chinese: () => boolean;
	portal: () => { to: string } | undefined;
	overlayPortal: () => { to: string } | undefined;
	media: () => readonly IssueInlineMedia[];
};

function sourceNode(
	name: "issueDiagram" | "issueFormula",
	kind: IssueSourceKind,
	options: RichNodeOptions
) {
	return Node.create({
		name,
		group: "block",
		atom: true,
		addAttributes() {
			return { id: { default: null }, source: { default: "" } };
		},
		parseHTML() {
			return [{ tag: `div[data-issue-block="${kind}"]` }];
		},
		renderHTML({ HTMLAttributes }) {
			return ["div", mergeAttributes(HTMLAttributes, { "data-issue-block": kind })];
		},
		addNodeView() {
			return ({ editor, getPos, node }) => {
				const dom = document.createElement("div");
				dom.dataset.issueBlock = kind;
				dom.dataset.issueBlockId = node.attrs.id ?? "";
				dom.contentEditable = "false";
				let current = $state.raw(node);
				const block = mount(IssueSourceBlock, {
					target: dom,
					props: {
						kind,
						get source() {
							return String(current.attrs.source ?? "");
						},
						get chinese() {
							return options.chinese();
						},
						get portal() {
							return options.overlayPortal();
						},
						onSourceChange(source) {
							const position = getPos();
							if (typeof position === "number")
								editor.view.dispatch(editor.state.tr.setNodeAttribute(position, "source", source));
						},
						onRemove() {
							const position = getPos();
							if (typeof position === "number")
								editor
									.chain()
									.focus()
									.deleteRange({ from: position, to: position + current.nodeSize })
									.run();
						},
					},
				});
				return {
					dom,
					stopEvent: () => true,
					ignoreMutation: () => true,
					update(next) {
						if (next.type !== node.type) return false;
						current = next;
						return true;
					},
					destroy() {
						void unmount(block);
					},
				};
			};
		},
	});
}

function mediaNode(options: RichNodeOptions) {
	return Node.create({
		name: "issueMedia",
		group: "block",
		atom: true,
		addAttributes() {
			return {
				id: { default: null },
				name: { default: "" },
				mime: { default: "" },
				src: { default: null },
				crop: {
					default: null,
					parseHTML: (element) => {
						try {
							return readImageCrop(JSON.parse(element.getAttribute("data-crop") ?? "null"));
						} catch {
							return null;
						}
					},
					renderHTML: ({ crop }) => (crop ? { "data-crop": JSON.stringify(crop) } : {}),
				},
			};
		},
		parseHTML() {
			return [{ tag: 'div[data-issue-block="media"]' }];
		},
		renderHTML({ HTMLAttributes }) {
			return ["div", mergeAttributes(HTMLAttributes, { "data-issue-block": "media" })];
		},
		addNodeView() {
			return ({ editor, getPos, node }) => {
				const dom = document.createElement("div");
				dom.dataset.issueBlock = "media";
				dom.contentEditable = "false";
				let current = $state.raw(node);
				const findMedia = () => options.media().find(({ id }) => id === current.attrs.id);
				const block = mount(IssueMediaBlock, {
					target: dom,
					props: {
						get name() {
							return String(current.attrs.name ?? "");
						},
						get mime() {
							return String(current.attrs.mime ?? "");
						},
						get src() {
							return current.attrs.src;
						},
						get crop() {
							return current.attrs.crop;
						},
						get media() {
							return findMedia();
						},
						get chinese() {
							return options.chinese();
						},
						get portal() {
							return options.portal();
						},
						get overlayPortal() {
							return options.overlayPortal();
						},
						onCropChange(crop) {
							const position = getPos();
							if (typeof position === "number")
								editor.view.dispatch(editor.state.tr.setNodeAttribute(position, "crop", crop));
						},
						onRemove() {
							const position = getPos();
							if (typeof position === "number")
								editor
									.chain()
									.focus()
									.deleteRange({ from: position, to: position + current.nodeSize })
									.run();
						},
					},
				});
				return {
					dom,
					stopEvent: () => true,
					ignoreMutation: () => true,
					update(next) {
						if (next.type !== node.type) return false;
						current = next;
						return true;
					},
					destroy() {
						void unmount(block);
					},
				};
			};
		},
	});
}

function sectionNodes(options: RichNodeOptions) {
	const title = Node.create({
		name: "issueSectionTitle",
		content: "inline*",
		defining: true,
		parseHTML() {
			return [{ tag: 'div[data-slot="issue-section-title"]' }];
		},
		renderHTML() {
			return ["div", { "data-slot": "issue-section-title" }, 0];
		},
	});

	const section = Node.create({
		name: "issueSection",
		group: "block",
		content: "issueSectionTitle block+",
		defining: true,
		addAttributes() {
			return {
				id: { default: null },
				open: {
					default: true,
					parseHTML: (element) => element.getAttribute("data-open") !== "false",
					renderHTML: ({ open }) => ({ "data-open": String(open) }),
				},
			};
		},
		parseHTML() {
			return [{ tag: 'div[data-issue-block="section"]' }];
		},
		renderHTML({ HTMLAttributes }) {
			return ["div", mergeAttributes(HTMLAttributes, { "data-issue-block": "section" }), 0];
		},
		addNodeView() {
			return ({ editor, getPos, node }) => {
				const dom = document.createElement("div");
				dom.dataset.issueBlock = "section";
				dom.dataset.issueBlockId = node.attrs.id ?? "";
				dom.className = "relative my-2 min-w-0";
				const contentDOM = document.createElement("div");
				contentDOM.dataset.issueSectionEditor = "";
				const chinese = options.chinese();
				contentDOM.lang = chinese ? "zh" : "en";
				contentDOM.style.setProperty(
					"--issue-section-title-placeholder",
					JSON.stringify(chinese ? "添加区块标题…" : "Add section title…")
				);
				contentDOM.style.setProperty(
					"--issue-section-body-placeholder",
					JSON.stringify(chinese ? "添加区块内容…" : "Add section content…")
				);
				const sectionLayout = [
					"grid min-w-0 gap-4 ps-6 leading-[22.5px]",
					"[&>:is([data-slot=issue-section-title],[data-slot=issue-section-title]+p):has(>.ProseMirror-trailingBreak)]:before:pointer-events-none",
					"[&>:is([data-slot=issue-section-title],[data-slot=issue-section-title]+p):has(>.ProseMirror-trailingBreak)]:before:absolute",
					"[&>:is([data-slot=issue-section-title],[data-slot=issue-section-title]+p):has(>.ProseMirror-trailingBreak)]:before:text-muted-foreground",
					"[&>[data-slot=issue-section-title]:has(>.ProseMirror-trailingBreak)]:before:content-[var(--issue-section-title-placeholder)]",
					"[&>[data-slot=issue-section-title]+p:has(>.ProseMirror-trailingBreak)]:before:content-[var(--issue-section-body-placeholder)]"
				].join(" ");
				const toggle = document.createElement("button");
				toggle.type = "button";
				toggle.contentEditable = "false";
				toggle.dataset.slot = "issue-section-toggle";
				toggle.className =
					"absolute start-0 top-px grid h-5 w-[21px] place-items-center rounded text-muted-foreground hover:bg-accent focus-visible:outline-1 focus-visible:-outline-offset-1 focus-visible:outline-ring";
				const triangle = document.createElement("span");
				triangle.setAttribute("aria-hidden", "true");
				triangle.className =
					"grid size-4 origin-center place-items-center text-[10px] transition-transform motion-reduce:transition-none";
				triangle.textContent = "▶";
				toggle.append(triangle);
				dom.append(toggle, contentDOM);
				let current = node;
				function reflect() {
					const open = current.attrs.open !== false;
					const chinese = options.chinese();
					const heading = current.firstChild?.textContent.trim();
					toggle.setAttribute("aria-expanded", String(open));
					toggle.setAttribute(
						"aria-label",
						`${open ? (chinese ? "收起区块" : "Collapse section") : chinese ? "展开区块" : "Expand section"}${heading ? ` · ${heading}` : ""}`
					);
					triangle.classList.toggle("rotate-90", open);
					dom.dataset.open = String(open);
					const layout = open
						? sectionLayout
						: `${sectionLayout} [&>*:not([data-slot=issue-section-title])]:hidden`;
					if (contentDOM.className !== layout) contentDOM.className = layout;
				}
				reflect();
				toggle.onclick = () => {
					const position = getPos();
					if (typeof position === "number")
						editor.view.dispatch(
							editor.state.tr.setNodeAttribute(position, "open", current.attrs.open === false)
						);
				};
				return {
					dom,
					contentDOM,
					stopEvent: (event) =>
						event.target instanceof HTMLElement && toggle.contains(event.target),
					ignoreMutation: (mutation) =>
						mutation.type !== "selection" &&
						(!contentDOM.contains(mutation.target) ||
							(mutation.type === "attributes" && mutation.target === contentDOM)),
					update(next) {
						if (next.type !== node.type) return false;
						current = next;
						reflect();
						return true;
					},
				};
			};
		},
	});
	return [title, section];
}

export function issueRichNodes(options: RichNodeOptions) {
	return [
		sourceNode("issueDiagram", "diagram", options),
		sourceNode("issueFormula", "formula", options),
		mediaNode(options),
		...sectionNodes(options),
	];
}

export type IssueImageCrop = { left: number; top: number; right: number; bottom: number };

export const fullImageCrop: IssueImageCrop = { left: 0, top: 0, right: 1, bottom: 1 };

export function readImageCrop(value: unknown): IssueImageCrop | undefined {
	if (!value || typeof value !== "object") return;
	const { left, top, right, bottom } = value as Partial<IssueImageCrop>;
	if (
		typeof left !== "number" ||
		typeof top !== "number" ||
		typeof right !== "number" ||
		typeof bottom !== "number"
	)
		return;
	if (!(left >= 0 && top >= 0 && right <= 1 && bottom <= 1 && right > left && bottom > top)) return;
	return { left, top, right, bottom };
}

export async function cropIssueImage(source: string, bounds: IssueImageCrop): Promise<Blob> {
	const image = new Image();
	if (/^https?:/.test(source)) image.crossOrigin = "anonymous";
	image.src = source;
	await image.decode();
	const left = Math.min(image.naturalWidth - 1, Math.round(bounds.left * image.naturalWidth));
	const top = Math.min(image.naturalHeight - 1, Math.round(bounds.top * image.naturalHeight));
	const width = Math.max(1, Math.round(bounds.right * image.naturalWidth) - left);
	const height = Math.max(1, Math.round(bounds.bottom * image.naturalHeight) - top);
	const canvas = document.createElement("canvas");
	canvas.width = width;
	canvas.height = height;
	const context = canvas.getContext("2d");
	if (!context) throw new Error("Canvas is unavailable");
	context.drawImage(image, left, top, width, height, 0, 0, width, height);
	return new Promise((resolve, reject) =>
		canvas.toBlob((value) => {
			if (value) resolve(value);
			else reject(new Error("Unable to crop image"));
		}, "image/png")
	);
}

import type { JSONContent } from "@tiptap/core";

export type IssueSourceKind = "diagram" | "formula";
export type IssueInlineMedia = { id: string; file: File };

export function issueMediaIds(content: JSONContent): Set<string> {
	const ids = new Set<string>();
	function visit(node: JSONContent) {
		if (node.type === "issueMedia" && typeof node.attrs?.id === "string") ids.add(node.attrs.id);
		node.content?.forEach(visit);
	}
	visit(content);
	return ids;
}

export function safeIssueMediaSrc(value: unknown) {
	const url = safeIssueLink(value);
	return url?.startsWith("https:") || url?.startsWith("http:") ? url : undefined;
}

export const richTextClass =
	"text-[15px] leading-6 font-[450] break-words [&_p+p]:mt-3 [&_ul]:my-2 [&_ul]:list-disc [&_ul]:ps-6 [&_ol]:my-2 [&_ol]:list-decimal [&_ol]:ps-6 [&_li_p]:my-0 [&_blockquote]:my-2 [&_blockquote]:border-s-2 [&_blockquote]:border-border [&_blockquote]:ps-3 [&_blockquote]:text-muted-foreground [&_h2]:mt-3 [&_h2]:text-xl [&_h2]:font-semibold [&_h3]:mt-3 [&_h3]:text-lg [&_h3]:font-semibold [&_h4]:mt-2 [&_h4]:font-semibold [&_code]:rounded-sm [&_code]:bg-muted [&_code]:px-1 [&_code]:font-mono [&_code]:text-[13px] [&_pre]:my-2 [&_pre]:rounded-lg [&_pre]:bg-muted [&_pre]:p-3 [&_pre_code]:bg-transparent [&_pre_code]:p-0 [&_a]:text-(--detail-accent) [&_a]:underline [&_hr]:my-3 [&_ul[data-type=taskList]]:list-none [&_ul[data-type=taskList]]:ps-0 [&_li[data-type=taskItem]]:flex [&_li[data-type=taskItem]]:items-start [&_li[data-type=taskItem]]:gap-2 [&_li[data-type=taskItem]>div]:min-w-0 [&_li[data-type=taskItem]>div]:flex-1 [&_li[data-type=taskItem]_input]:size-3.5 [&_li[data-type=taskItem]_input]:accent-(--detail-accent) [&_li[data-type=taskItem]_input:focus-visible]:outline-1 [&_li[data-type=taskItem]_input:focus-visible]:-outline-offset-1 [&_li[data-type=taskItem]_input:focus-visible]:outline-ring";

export function descriptionFromText(value: string): JSONContent {
	return {
		type: "doc",
		content: value.split(/\r?\n/).map((text) => ({
			type: "paragraph",
			content: text ? [{ type: "text", text }] : [],
		})),
	};
}

export function safeIssueLink(value: unknown) {
	if (typeof value !== "string") return;
	try {
		const url = new URL(value.trim());
		if (["http:", "https:", "mailto:"].includes(url.protocol)) return url.href;
	} catch {
		return undefined;
	}
}
